using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class MakeFisherWooden
{
 const string D="Assets/Prefabs/Workshop/Fisher/";
 static Material Mat(string name,Color color){var m=new Material(Shader.Find("Standard")){name=name,color=color};m.SetFloat("_Glossiness",.14f);AssetDatabase.CreateAsset(m,D+name+".mat");return m;}
 static void Swap(Transform target,Transform source,Material material){var mf=target.GetComponentInChildren<MeshFilter>();var sm=source.GetComponentInChildren<MeshFilter>();if(mf==null||sm==null)throw new Exception("Missing mesh "+target.name);mf.sharedMesh=sm.sharedMesh;var r=mf.GetComponent<Renderer>();r.sharedMaterials=source.GetComponentInChildren<Renderer>().sharedMaterials.Select(m=>material).ToArray();var col=mf.GetComponent<MeshCollider>();if(col!=null)col.sharedMesh=mf.sharedMesh;}
 static void Capture(Transform h,Vector3 pos,Vector3 target,string file,float fov){var g=new GameObject("Temporary_Fisher_Wood_Camera");var rt=new RenderTexture(1400,1000,24);var tex=new Texture2D(1400,1000,TextureFormat.RGB24,false);var previous=RenderTexture.active;var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.enabled).ToArray();try{foreach(var c in canvases)c.enabled=false;var cam=g.AddComponent<Camera>();cam.transform.position=h.TransformPoint(pos);cam.transform.LookAt(h.TransformPoint(target));cam.fieldOfView=fov;cam.farClipPlane=120;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.19f,.25f,.29f);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1400,1000),0,0);tex.Apply();File.WriteAllBytes("Docs/assets/examples/"+file+".png",tex.EncodeToPNG());}finally{foreach(var c in canvases)c.enabled=true;RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/CastleServicesWorkshop.unity"||scene.isDirty||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Saved castle Edit Mode required");var h=GameObject.Find("Castle_Services_Prototype").transform.Find("03_Service_Houses/02_Armory");if(File.Exists(D+"Fisher_WarmTimber.mat"))throw new Exception("Already wooden; inspect instead of overwriting");Directory.CreateDirectory("Library/WorkshopBackups/DB-ON-079-Wood");File.Copy(scene.path,"Library/WorkshopBackups/DB-ON-079-Wood/OwnerSaved.unity",true);
  var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Workshop/WoodenCottage_01.prefab").transform;var timber=Mat("Fisher_WarmTimber",new Color(.44f,.29f,.16f));var dark=Mat("Fisher_DarkBeams",new Color(.25f,.16f,.085f));var light=Mat("Fisher_FloorBoards",new Color(.49f,.35f,.21f));
  var sw=source.Find("02_Walls");foreach(Transform part in h.Find("02_Walls")){if(!part.gameObject.activeSelf)continue;Transform match;if(part.name.Contains("Window"))match=sw.Cast<Transform>().First(t=>t.name.Contains("Window"));else if(part.name.StartsWith("Door_"))match=sw.Find(part.name);else match=sw.Cast<Transform>().First(t=>t.name=="wallWood");Swap(part,match,timber);}
  foreach(Transform part in h.Find("03_Frame"))Swap(part,source.Find("03_Frame").GetChild(0),dark);
  foreach(string group in new[]{"01_Floor","05_Porch"})foreach(Transform part in h.Find(group))Swap(part,source.Find(group).GetChild(0),light);
  var backing=GameObject.CreatePrimitive(PrimitiveType.Cube);backing.name="18_Wooden_Subfloor";backing.transform.SetParent(h,false);backing.transform.localPosition=new Vector3(0,.42f,0);backing.transform.localScale=new Vector3(8.3f,.06f,5.95f);backing.GetComponent<Renderer>().sharedMaterial=dark;UnityEngine.Object.DestroyImmediate(backing.GetComponent<Collider>());
  h.Find("10_Castle_Masonry").gameObject.SetActive(false);
  var roof=h.Find("04_Roof/Sealed_Roof_Assembly");foreach(string name in new[]{"Front_Gable","Rear_Gable"})roof.Find(name).GetComponent<Renderer>().sharedMaterial=timber;var underside=roof.Find("Continuous_Pitched_Roof").GetComponent<Renderer>();underside.sharedMaterials=underside.sharedMaterials.Select(m=>dark).ToArray();
  if(h.Find("16_Run_Interior").gameObject.activeSelf||!h.Find("17_Boarded_Entrance").gameObject.activeSelf)throw new Exception("Interior/barrier state unexpected");Physics.SyncTransforms();var probe=new GameObject("Temporary_Fisher_Wood_Probe");Vector3 end;try{var cc=probe.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.35f;cc.center=new Vector3(0,.9f,0);cc.stepOffset=.3f;probe.transform.position=h.TransformPoint(new Vector3(0,.55f,-4.8f));Physics.SyncTransforms();for(int i=0;i<100;i++)cc.Move(h.TransformVector(new Vector3(0,0,.04f))+Vector3.down*.025f);end=h.InverseTransformPoint(probe.transform.position);if(end.z>-3.3f)throw new Exception("Barrier failed "+end);}finally{UnityEngine.Object.DestroyImmediate(probe);}
  Capture(h,new Vector3(-10,6,-13),new Vector3(0,1.7f,0),"Fisher_Wooden_Exterior",49);Capture(h,new Vector3(0,2,-2.4f),new Vector3(0,1.2f,1.4f),"Fisher_Wooden_Empty_Interior",100);
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");Selection.activeGameObject=h.gameObject;SceneView.lastActiveSceneView?.LookAt(h.TransformPoint(new Vector3(0,1.8f,0)),h.rotation*Quaternion.Euler(22,-30,0),8,false,true);var report="PASS: real wooden meshes on walls, posts, floor and porch; stone overlay disabled; empty interior retained; blocked entrance="+end+"; scene saved. Roof tiles, building transforms and source prefab retained.";File.WriteAllText("Docs/assets/examples/FISHER_WOOD_VALIDATION.txt",report);return report;
 }
}
